from decimal import Decimal, ROUND_HALF_UP
from typing import Any, Dict, List


def calculate_getGrandTotal(request: Dict[str, Any]) -> Dict[str, str]:
    """
    Compute order monetary components and the grand total.

    Expected output keys (all present as strings with two decimal places):
        sub_total
        total_shipping
        total_sales_tax
        order_other_adjustment_total
        order_global_adjustments
        grand_total
    """

    def to_decimal(value: Any) -> Decimal:
        """Convert a value to Decimal safely."""
        if isinstance(value, Decimal):
            return value
        # Preserve exact string representation for floats/ints
        return Decimal(str(value)) if value is not None else Decimal("0")

    # ---------- Sub‑total ----------
    if "cart_lines" in request and isinstance(request["cart_lines"], list):
        sub_total = sum(
            (to_decimal(line.get("item_sub_total", "0")) for line in request["cart_lines"]),
            Decimal("0"),
        )
    else:
        sub_total = to_decimal(request.get("sub_total", "0"))

    # ---------- Shipping ----------
    if "ship_info" in request and isinstance(request["ship_info"], list):
        total_shipping = sum(
            (to_decimal(info.get("ship_estimate", "0")) for info in request["ship_info"]),
            Decimal("0"),
        )
    else:
        total_shipping = to_decimal(request.get("total_shipping", "0"))

    # ---------- Sales Tax ----------
    if "ship_info" in request and isinstance(request["ship_info"], list):
        total_sales_tax = sum(
            (to_decimal(info.get("total_tax", "0")) for info in request["ship_info"]),
            Decimal("0"),
        )
    else:
        total_sales_tax = to_decimal(request.get("total_sales_tax", "0"))

    # ---------- Other Adjustments ----------
    if "adjustments" in request and isinstance(request["adjustments"], list):
        other_adj_total = Decimal("0")
        for adj in request["adjustments"]:
            amount = to_decimal(adj.get("amount", "0"))
            if adj.get("is_percent"):
                # percentage of sub_total
                amount = (sub_total * amount) / Decimal("100")
            other_adj_total += amount
        order_other_adjustment_total = other_adj_total
    else:
        order_other_adjustment_total = to_decimal(
            request.get("order_other_adjustment_total", "0")
        )

    # ---------- Global Adjustments ----------
    if "global_adjustments" in request and isinstance(request["global_adjustments"], list):
        global_adj_total = Decimal("0")
        for adj in request["global_adjustments"]:
            ship_group_seq_id = adj.get("ship_group_seq_id")
            # Include only if None or exactly "_NA_"
            if ship_group_seq_id is not None and ship_group_seq_id != "_NA_":
                continue
            amount = to_decimal(adj.get("amount", "0"))
            if adj.get("is_percent"):
                amount = (sub_total * amount) / Decimal("100")
            global_adj_total += amount
        order_global_adjustments = global_adj_total
    else:
        order_global_adjustments = to_decimal(
            request.get("order_global_adjustments", "0")
        )

    # ---------- Grand Total ----------
    grand_total = (
        sub_total
        + total_shipping
        + total_sales_tax
        + order_other_adjustment_total
        + order_global_adjustments
    )

    # Helper to format Decimal with two decimal places, preserving trailing zeros
    def fmt(value: Decimal) -> str:
        return str(value.quantize(Decimal("0.00"), rounding=ROUND_HALF_UP))

    return {
        "sub_total": fmt(sub_total),
        "total_shipping": fmt(total_shipping),
        "total_sales_tax": fmt(total_sales_tax),
        "order_other_adjustment_total": fmt(order_other_adjustment_total),
        "order_global_adjustments": fmt(order_global_adjustments),
        "grand_total": fmt(grand_total),
    }
